export function run(source) { const fn = api.get(); fn(source); }
export function aliased(source) { const held = source; const fn = api.get(); fn(held); }
export function destructured(source) { const { fn } = api.pair(); fn(source); }
function getFn() { return api.get(); }
export function returned(source) { const fn = getFn(); fn(source); }
export function chained(source) { relay(source); }
export function later(source) { queueMicrotask(() => { const fn = api.get(); fn(source); }); }
export { run as reexported };
export const tools = { run(source) { const fn = api.get(); fn(source); } };
